      --bg: #f5f7fb;
      --card: rgba(255, 255, 255, 0.9);
      --card-border: rgba(15, 23, 42, 0.08);
      --text: #0f172a;
      --muted: #64748b;
      --accent: #2563eb;
      --accent-soft: #dbeafe;
      --shadow: 0 20px 60px rgba(15, 23, 42, 0.08);
      --radius: 20px;
