       --card: rgba(255, 255, 255, 0.9);
       --card-border: rgba(15, 23, 42, 0.08);
       --text: #0f172a;
       --muted: #64748b;
       --accent: #2563eb;
       --accent-soft: #dbeafe;
       --shadow: 0 20px 60px rgba(15, 23, 42, 0.08);
       --radius: 20px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, #ffffff 0%, rgba(255, 255, 255, 0) 40%),
         linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
       min-height: 100vh;
     }

     .page {
       width: min(920px, calc(100% - 32px));
       margin: 40px auto;
     }

     .hero {
       margin-bottom: 24px;
       padding: 28px;
       border: 1px solid var(--card-border);
       border-radius: var(--radius);
       background: var(--card);
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: var(--accent-soft);
       color: var(--accent);
       font-size: 0.85rem;
       font-weight: 600;
       margin-bottom: 14px;
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(2rem, 4vw, 3rem);
       line-height: 1.05;
     }

     .subtitle {
       margin: 0;
       max-width: 60ch;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       padding: 24px;
       border: 1px solid var(--card-border);
       border-radius: var(--radius);
       background: var(--card);
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .question-title {
       margin: 0 0 8px;
       font-size: 1.15rem;
     }

     .help-text {
       margin: 0 0 18px;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .choices {
       display: grid;
       gap: 12px;
     }

     .choice {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid #e2e8f0;
       border-radius: 14px;
       background: #fff;
       transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
       cursor: pointer;
     }

     .choice:hover {
       border-color: #bfdbfe;
       box-shadow: 0 10px 24px rgba(37, 99, 235, 0.08);
       transform: translateY(-1px);
     }

     .choice input {
       width: 18px;
       height: 18px;
       accent-color: var(--accent);
       flex: 0 0 auto;
     }

     .choice span {
       font-size: 0.98rem;
     }

     .actions {
       display: flex;
       justify-content: flex-end;
       margin-top: 6px;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 14px;
       background: linear-gradient(135deg, #2563eb, #1d4ed8);
       color: white;
       padding: 14px 22px;
       font-size: 1rem;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 16px 30px rgba(37, 99, 235, 0.25);
       transition: transform 0.2s ease, box-shadow 0.2s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 20px 34px rgba(37, 99, 235, 0.3);
     }

     .result {
       margin-top: 18px;
       padding: 16px 18px;
       border-radius: 16px;
       background: #eff6ff;
       color: #1e3a8a;
       border: 1px solid #bfdbfe;
       display: none;
     }

     .result.visible {
       display: block;
     }

     @media (max-width: 640px) {
       .page {
         width: min(100% - 20px, 920px);
         margin: 20px auto;
       }

       .hero,
       .form-field {
         padding: 20px;
       }
     }
   </style>
 </head>
 <body>
   <main class="page">
     <section class="hero" aria-labelledby="quiz-title">
       <div class="eyebrow">Quiz</div>
       <h1 id="quiz-title">Computer Languages</h1>
       <p class="subtitle">
         Select all answers you think apply. Each question allows multiple selections.
       </p>
     </section>

     <form id="quiz-form">
       <div class="form-field">
         <h2 class="question-title">1. Which of these are programming languages?</h2>
         <p class="help-text">Pick every option that is commonly used to write software.</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML"><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="Ruby"><span>Ruby</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">2. Which of these are compiled languages?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q2" value="C"><span>C</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Go"><span>Go</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Python"><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Rust"><span>Rust</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">3. Which of these are commonly used for web development?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q3" value="JavaScript"><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="TypeScript"><span>TypeScript</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="CSS"><span>CSS</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="SQL"><span>SQL</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
       </div>

       <div class="result" id="result" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selections = ['q1', 'q2', 'q3'].map((name) => {
         const selected = [...form.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value);
         return selected.length ? selected.join(', ') : 'No answers selected';
       });

       result.textContent = `Submitted selections — Q1: ${selections[0]} | Q2: ${selections[1]} | Q3: ${selections[2]}`;
       result.classList.add('visible');
     });
   </script>
 </body>
 </html>

')
